	@Test
	void functionCallTest() {

		ChatMemory chatMemory = new InMemoryChatMemory();

		// @formatter:off
		var chatClient = ChatClient.builder(chatModel)
			.defaultSystem("""
                        You are an assistant project manager expert at managing many resources and schedules.
