I use the following workaround:

```java
import org.springframework.ai.model.tool.internal.ToolCallReactiveContextHolder;
import org.springframework.ai.tool.ToolCallback;
import org.springframework.ai.tool.definition.ToolDefinition;
import org.springframework.security.core.context.SecurityContext;
import org.springframework.security.core.context.SecurityContextHolder;

public class SecurityContextPropagatingToolCallback implements ToolCallback {

    private final ToolCallback delegate;

    public SecurityContextPropagatingToolCallback(ToolCallback delegate) {
        this.delegate = delegate;
    }

    @Override
    public ToolDefinition getToolDefinition() {
        return delegate.getToolDefinition();
    }

    @Override
    public String call(String toolInput) {
        var securityContext = ToolCallReactiveContextHolder.getContext()
                .<SecurityContext>get("org.springframework.security.core.context.SecurityContext");
        try {
            SecurityContextHolder.setContext(securityContext);
            return delegate.call(toolInput);
        } finally {
            SecurityContextHolder.clearContext();
        }
    }

}
```

