```java
import com.google.api.gax.core.FixedCredentialsProvider;
import com.google.api.gax.retrying.RetrySettings;
import com.google.auth.oauth2.GoogleCredentials;
import com.google.cloud.vertexai.Transport;
import com.google.cloud.vertexai.VertexAI;
import com.google.cloud.vertexai.api.PredictionServiceClient;
import com.google.cloud.vertexai.api.PredictionServiceSettings;
import lombok.RequiredArgsConstructor;
import org.springframework.ai.model.vertexai.autoconfigure.gemini.VertexAiGeminiConnectionProperties;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;
import org.springframework.context.annotation.Primary;
import org.threeten.bp.Duration;

import java.io.IOException;
import java.io.InputStream;

@Configuration
@RequiredArgsConstructor
public class VertexAiCustomConfig {


    private static final Duration IDLE_TIMEOUT = Duration.ofSeconds(60);
    private static final Duration RPC_TIMEOUT = Duration.ofSeconds(120); 
    private final VertexAiGeminiConnectionProperties connectionProperties;

    @Bean
    @Primary
    public VertexAI vertexAI() {
        try {
            var vertexAIBuilder = new VertexAI.Builder()
                    .setProjectId(connectionProperties.getProjectId())
                    .setLocation(connectionProperties.getLocation())
                    .setTransport(Transport.GRPC);

            try (InputStream credentialsStream = connectionProperties.getCredentialsUri().getInputStream()) {
                GoogleCredentials credentials = GoogleCredentials.fromStream(credentialsStream);
                vertexAIBuilder.setCredentials(credentials);
            }
            vertexAIBuilder.setPredictionClientSupplier(this::createCustomPredictionServiceClientForGrpc);

            return vertexAIBuilder.build();

        } catch (IOException e) {
            throw new IllegalStateException("Failed to initialize VertexAI client with gRPC transport.", e);
        }
    }

    private PredictionServiceClient createCustomPredictionServiceClientForGrpc() {
        try {
            RetrySettings retrySettings = RetrySettings.newBuilder()
                    .setTotalTimeout(RPC_TIMEOUT)
                    .build();

            PredictionServiceSettings.Builder settingsBuilder = PredictionServiceSettings.newBuilder();

            settingsBuilder.generateContentSettings().setRetrySettings(retrySettings);
            settingsBuilder.streamGenerateContentSettings()
                    .setIdleTimeout(IDLE_TIMEOUT)
                    .setRetrySettings(retrySettings);

            try (InputStream credentialsStream = connectionProperties.getCredentialsUri().getInputStream()) {
                GoogleCredentials credentials = GoogleCredentials.fromStream(credentialsStream)
                        .createScoped(PredictionServiceSettings.getDefaultServiceScopes());
                settingsBuilder.setCredentialsProvider(FixedCredentialsProvider.create(credentials));
            }
            String location = connectionProperties.getLocation();
            if (location != null) {
                if (location.equals("global")) {
                    settingsBuilder.setEndpoint("aiplatform.googleapis.com:443");
                } else {
                    String endpoint = String.format("%s-aiplatform.googleapis.com:443", location);
                    settingsBuilder.setEndpoint(endpoint);
                }
            }
            return PredictionServiceClient.create(settingsBuilder.build());

        } catch (IOException e) {
            throw new IllegalStateException("Failed to create custom gRPC PredictionServiceClient for Vertex AI.", e);
        }
    }
}

```

