below code is my tmp solution.
I just remove the extra_body field from request using intercepor.

```
@Configuration
class RestClientConfig {

    companion object {
        private const val OPENAI_HOST = "api.openai.com"
        private const val CHAT_COMPLETIONS_PATH = "/v1/chat/completions"
        private const val EXTRA_BODY = "extra_body"
    }

    private val objectMapper = ObjectMapper()

    @Bean
    fun extraBodyRemover(): RestClientCustomizer {
        return RestClientCustomizer { builder: RestClient.Builder ->
            builder.requestInterceptor { request, body, execution ->
                if (!isTargetRequest(request.uri)) {
                    return@requestInterceptor execution.execute(request, body)
                }

                val isJson = request.headers.contentType?.isCompatibleWith(MediaType.APPLICATION_JSON) == true
                if (!isJson) {
                    return@requestInterceptor execution.execute(request, body)
                }

                val outgoingBody = removeExtraBodyIfPresent(body)
                execution.execute(request, outgoingBody)
            }
        }
    }

    private fun isTargetRequest(uri: URI): Boolean =
        uri.host == OPENAI_HOST && uri.path == CHAT_COMPLETIONS_PATH

    private fun removeExtraBodyIfPresent(jsonBytes: ByteArray): ByteArray =
        try {
            val root = objectMapper.readTree(jsonBytes)
            if (root is ObjectNode && root.has(EXTRA_BODY)) {
                val mutableObj = root.deepCopy<ObjectNode>()
                mutableObj.remove(EXTRA_BODY)
                objectMapper.writeValueAsBytes(mutableObj)
            } else {
                jsonBytes
            }
        } catch (_: Exception) {
            jsonBytes
        }
}
```

