    }

    boolean hasToolCalls = list.stream()
        .map(this::safeAssistantMessage)
        .filter(Objects::nonNull)
        .anyMatch(am -> !CollectionUtils.isEmpty(am.getToolCalls()));

    if (!hasToolCalls) {
        return Flux.fromIterable(list);
    }

    // tool call handling...
});`
