<details>
<summary><code>BedrockThinkingToolReplayIT.java</code></summary>

```java
package org.springframework.ai.bedrock.converse;

import java.time.Duration;
import java.util.ArrayList;
import java.util.List;
import java.util.Map;

import org.junit.jupiter.api.Test;
import software.amazon.awssdk.auth.credentials.ProfileCredentialsProvider;
import software.amazon.awssdk.regions.Region;

import org.springframework.ai.chat.messages.AssistantMessage;
import org.springframework.ai.chat.messages.Message;
import org.springframework.ai.chat.messages.UserMessage;
import org.springframework.ai.chat.model.ChatResponse;
import org.springframework.ai.chat.prompt.Prompt;
import org.springframework.ai.model.tool.DefaultToolCallingManager;
import org.springframework.ai.model.tool.ToolCallingManager;
import org.springframework.ai.model.tool.ToolExecutionResult;
import org.springframework.ai.tool.function.FunctionToolCallback;

import static org.assertj.core.api.Assertions.assertThat;

/**
 * Live reproduction for gh-6413 / PR gh-6414: extended thinking + tool use.
 */
class BedrockThinkingToolReplayIT {

	private static final String MODEL_ID = "eu.anthropic.claude-sonnet-4-6";

	private BedrockProxyChatModel chatModel() {
		return BedrockProxyChatModel.builder()
			.credentialsProvider(ProfileCredentialsProvider.create("bedrock"))
			.region(Region.EU_WEST_1)
			.timeout(Duration.ofMinutes(3))
			.options(BedrockChatOptions.builder().model(MODEL_ID).build())
			.build();
	}

	@SuppressWarnings({ "unchecked", "rawtypes" })
	private static Map<String, String> thinkingEnabled(int budgetTokens) {
		return (Map) Map.of("thinking", Map.of("type", "enabled", "budget_tokens", budgetTokens));
	}

	@Test
	void extendedThinkingWithToolUseCompletesAndReplaysReasoning() {

		var chatModel = chatModel();
		ToolCallingManager toolCallingManager = DefaultToolCallingManager.builder().build();

		// Anthropic requires temperature == 1 when thinking is enabled.
		var options = BedrockChatOptions.builder()
			.model(MODEL_ID)
			.maxTokens(4096)
			.temperature(1.0)
			.requestParameters(thinkingEnabled(2048))
			.toolCallbacks(List.of(FunctionToolCallback.builder("getCurrentWeather", new MockWeatherService())
				.description("Get the weather in location. Return in 36°C format")
				.inputType(MockWeatherService.Request.class)
				.build()))
			.build();

		List<Message> messages = new ArrayList<>(List.of(new UserMessage(
				"What's the weather like in San Francisco, Tokyo and Paris? Return the result in Celsius.")));

		var prompt = new Prompt(messages, options);

		ChatResponse response = chatModel.call(prompt);

		// Reasoning is attached to the tool-call generation, not a leading text block.
		assertThat(response.hasToolCalls()).as("model should call the weather tool").isTrue();
		AssistantMessage toolTurn = response.getResults()
			.stream()
			.map(g -> g.getOutput())
			.filter(m -> !m.getToolCalls().isEmpty())
			.findFirst()
			.orElseThrow();
		assertThat(toolTurn).isInstanceOf(BedrockAssistantMessage.class);
		assertThat(((BedrockAssistantMessage) toolTurn).hasReasoningContents())
			.as("reasoning block must be preserved on the tool-call turn for replay (gh-6413)")
			.isTrue();

		// Drive the tool-calling loop. Before the fix, the call below threw
		// ValidationException on the tool-result turn.
		int guard = 0;
		while (response.hasToolCalls() && guard++ < 5) {
			ToolExecutionResult toolExecutionResult = toolCallingManager.executeToolCalls(prompt, response);
			prompt = new Prompt(toolExecutionResult.conversationHistory(), options);
			response = chatModel.call(prompt);
		}

		assertThat(response.hasToolCalls()).as("loop should terminate").isFalse();
		assertThat(response.getResult().getOutput().getText()).contains("30", "10", "15");
	}

}
```
</details>

Looks good to me. Thanks again for jumping on this, will be great to have it in 2.0.1.

